<?php defined('ABSPATH') || exit;$base=home_url('/companion/');$root='dungeon-master/campaigns/'.$campaign->id().'/locations';$active=array_values(array_filter($locations??[],static fn($l):bool=>!$l->isArchived()));$archived=array_values(array_filter($locations??[],static fn($l):bool=>$l->isArchived()));$byId=[];foreach(($locations??[]) as $item){$byId[$item->id()]=$item;} ?>
<section class="gmrc-gazetteer" aria-labelledby="gmrc-gazetteer-title"><header class="gmrc-gazetteer__hero"><div><p class="gmrc-dm-desk__eyebrow">Keeper’s Workshop · Gazetteer</p><h1 id="gmrc-gazetteer-title">The Keeper’s Gazetteer</h1><p>Give the places of <strong><?php echo esc_html($campaign->name()); ?></strong> a permanent campaign record before maps, clues and strings begin to point at them.</p></div><?php if(!$campaign->isArchived()): ?><a class="gmrc-gazetteer-button" href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/create',$base)); ?>">Record New Place</a><?php endif; ?></header><?php if(($flash['success']??null)): ?><p class="gmrc-gazetteer-flash" role="status"><?php echo esc_html($flash['success']); ?></p><?php endif; ?>
<nav class="gmrc-gazetteer-summary" aria-label="Gazetteer summary"><span><strong><?php echo count($active); ?></strong> active places</span><span><strong><?php echo count(array_filter($active,static fn($l):bool=>$l->parentId()!=='')); ?></strong> nested places</span><span><strong><?php echo count(array_filter($active,static fn($l):bool=>$l->visibility()==='players')); ?></strong> player-visible</span></nav>
<?php if($active===[]): ?><article class="gmrc-gazetteer-empty"><div aria-hidden="true">🗺️</div><h2>The map has names waiting to be written</h2><p>Record a realm, settlement, building, dungeon, room or landmark. Locations can later contain other locations and become anchors for the Conspiracy Board and Tabletop.</p></article><?php else: ?><div class="gmrc-gazetteer-grid"><?php foreach($active as $place): ?><article class="gmrc-gazetteer-card"><div class="gmrc-gazetteer-card__meta"><span><?php echo esc_html($place->typeLabel()); ?></span><span><?php echo $place->isKeeperOnly()?'🔒 Keeper only':'◉ Player-visible'; ?></span></div><h2><?php echo esc_html($place->name()); ?></h2><?php if($place->parentId()!==''&&isset($byId[$place->parentId()])): ?><p class="gmrc-gazetteer-card__parent">Inside <?php echo esc_html($byId[$place->parentId()]->name()); ?></p><?php endif; ?><p><?php echo esc_html($place->summary()!==''?$place->summary():'No at-a-glance description has been written yet.'); ?></p><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$place->id(),$base)); ?>">Open place <span aria-hidden="true">→</span></a></article><?php endforeach; ?></div><?php endif; ?>
<?php if($archived!==[]): ?><details class="gmrc-gazetteer-archive"><summary>Archived places (<?php echo count($archived); ?>)</summary><div class="gmrc-gazetteer-grid"><?php foreach($archived as $place): ?><article class="gmrc-gazetteer-card"><h2><?php echo esc_html($place->name()); ?></h2><p><?php echo esc_html($place->typeLabel()); ?> · Archived</p><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$place->id(),$base)); ?>">Read archived place</a></article><?php endforeach; ?></div></details><?php endif; ?><p class="gmrc-gazetteer-back"><a href="<?php echo esc_url(add_query_arg('gmrc_route','dungeon-master/campaigns/'.$campaign->id(),$base)); ?>">← Back to Campaign Command Centre</a></p></section>
